    PLAYER_ITEMS: '[class*="control-bar-button-"], [class*="control-bar-buttons-menu-button-"], [class*="player-button-"], .dx-seek[role="button"], .dxp-player-btn, [class*="menu-layer"] [tabindex], [class*="menu-layer"] [class*="button-container"]',

